demo.program:
// OpenMDAO idea demo (simulated model)
console.log('disciplines -> one model -> derivatives -> optimum');
console.log('MDO in Python');

// Component demo (simulated model)
var comp={inputs:['x'],outputs:['y'],partials:true};
console.log('component: '+comp.inputs+' -> '+comp.outputs+' partials='+comp.partials);

// Group demo (simulated model)
var tree={vehicle:['aero','struct','prop']};
console.log('model tree: vehicle -> '+tree.vehicle.join(','));
console.log('one model, many teams');

// Driver demo (simulated model)
var drivers=['SLSQP','SNOPT','genetic','DOE'];
for(var i=0;i<drivers.length;i++){console.log('driver: '+drivers[i]);}
console.log('right driver per problem');

// Derivative demo (simulated model)
var f=function(x){return x*x+2*x;}, h=1e-6, x=3;
var d=(f(x+h)-f(x-h))/(2*h);
console.log('df/dx at x=3: '+d.toFixed(3)+' (analytic 8)');
console.log('derivatives drive optimization');

// Coupling demo (simulated model)
var y=1;
for(var i=0;i<6;i++){y=2+0.5*y;}
console.log('coupled solve converged: y='+y.toFixed(4));

// Dymos demo (simulated model)
console.log('Dymos: trajectory as optimization');
console.log('collocation converged');

// Wing trade demo (simulated model)
var span=10, drag=100/span, weight=span*8;
console.log('span '+span+': drag '+drag.toFixed(1)+' weight '+weight);
console.log('MDO finds the trade');

// Cycle demo (simulated model)
console.log('pyCycle: SFC minimized at PR=32');
console.log('engine + airframe co-optimized');

// N2 demo (simulated model)
var comps=['aero','struct','prop'];
for(var i=0;i<comps.length;i++){for(var j=0;j<comps.length;j++){if(i!==j)console.log(comps[i]+' -> '+comps[j]);}}
console.log('N2 connections mapped');

// GA demo (simulated model)
var best=1e9;
for(var i=0;i<20;i++){var v=Math.abs(Math.sin(i)*10-3);if(v<best)best=v;}
console.log('GA best: '+best.toFixed(3));

// Pareto demo (simulated model)
var pts=[[1,9],[3,5],[6,2]];
for(var i=0;i<pts.length;i++){console.log('design: fuel '+pts[i][0]+' cost '+pts[i][1]);}
console.log('Pareto front: '+pts.length+' trades');

// Surrogate demo (simulated model)
console.log('surrogate: 1000x faster, 2% error');
console.log('MetaModel swapped in');

// UQ demo (simulated model)
var n=100, s=0;
for(var i=0;i<n;i++){s+=10+((i*37)%7)-3;}
console.log('mean '+(s/n).toFixed(2)+' robust to variation');

// Workflow demo (simulated model)
var w=['components','tree','couplings','driver','optimize'];
for(var i=0;i<w.length;i++){console.log((i+1)+'. '+w[i]);}
console.log('MDO workflow complete');
